contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractEthBefore = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractEthAfter = address(c).balance;

        assert(
            reverted
                ? balAfter == balBefore
                : (balAfter == 0 && contractEthAfter <= contractEthBefore && contractEthBefore - contractEthAfter == balBefore)
        );
    }

    receive() external payable {}
}

