// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 contractEthBefore = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 contractEthAfter = address(c).balance;
        assertTrue(reverted
                ? balAfter == balBefore
                : (balAfter == 0 && contractEthAfter <= contractEthBefore && contractEthBefore - contractEthAfter == balBefore));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
